import './ActivityFeed.css';
import ActivityItem from './ActivityItem';

// props.banner ('home' | 'notifications') adds a page banner and makes the
// heading sticky (banner CSS in ActivityFeed.css). Without it the heading is
// unchanged, so the Profile page (no title, no banner) looks the same as before.
export default function ActivityFeed(props) {
  const headingClass = props.banner
    ? `activity_feed_heading banner banner_${props.banner}`
    : 'activity_feed_heading';
  return (
    <div className='activity_feed'>
      <div className={headingClass}>
        <div className='title'>{props.title}</div>
      </div>
      <div className='activity_feed_collection'>
        {props.activities.map(activity => {
        return  <ActivityItem setReplyActivity={props.setReplyActivity} setPopped={props.setPopped} key={activity.uuid} activity={activity} />
        })}
      </div>
    </div>
  );
}

.activity_feed {
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
}

.activity_feed_collection {
  display: flex;
  flex-direction: column;
}

.activity_feed_heading {
  padding: 16px;
  padding-bottom: 48px;
  border-bottom: solid 1px rgb(58,63,78);
}

.activity_feed_heading .title{
  color: #fff;
  font-weight: 800;
  font-size: 20px;
}

/* Page banners + locked header (backlog #43, banners by C 2026-10-06).
   .content is the scroll container (App.css), so position: sticky pins the
   heading to the top of the centre column while the feed scrolls under it.
   The SVGs are BACKGROUND images, never inlined: all four reuse the ids
   "glow"/"rule", which would collide if two were inlined in one page.
   Each SVG has an opaque #000 base, so posts never show through. */
.activity_feed_heading.banner {
  position: sticky;
  top: 0;
  z-index: 3;
  background-color: #000;
  background-repeat: no-repeat;
  background-position: right center;
  background-size: auto 100%;
}

.activity_feed_heading.banner_home {
  background-image: url('./banners/banner_home.svg');
}

.activity_feed_heading.banner_notifications {
  background-image: url('./banners/banner_notifications.svg');
}

.activity_feed_heading.banner_people {
  background-image: url('./banners/banner_people.svg');
}

/* Popups (reply, edit profile) must stay above the sticky header (z-index 3). */
.popup_form_wrap {
  z-index: 1000;
}

section.message_groups {
  background: #000;
  border-right: solid 1px rgb(58,63,78);
  padding: 0px;
}

.message_group_feed_heading {
  padding: 16px;
  padding-bottom: 48px;
  border-bottom: solid 1px rgb(58,63,78);
}

.message_group_feed_heading .title{
  color: #fff;
  font-weight: 800;
  font-size: 20px;
}

.message_group_feed {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.message_group_feed_collection {
  flex-grow: 1;
  overflow: auto;
}

/* Messages banner (C 2026-10-06). This heading is already locked: only
   .message_group_feed_collection scrolls. Background image, not inlined
   (shared SVG ids). Right-anchored so the icons stay visible in the
   narrower message column; 85% height keeps the
   artwork clear of the "Messages" title. */
.message_group_feed_heading {
  background-color: #000;
  background-image: url('./banners/banner_messages.svg');
  background-repeat: no-repeat;
  background-position: right bottom;
  background-size: auto 85%;
}

import './HomeFeedPage.css';
import React from "react";
import { useLocation, useNavigate } from 'react-router-dom';

import DesktopNavigation  from '../components/DesktopNavigation';
import DesktopSidebar     from '../components/DesktopSidebar';
import ActivityFeed from '../components/ActivityFeed';
import ActivityForm from '../components/ActivityForm';
import ReplyForm from '../components/ReplyForm';        

import { signOut } from 'aws-amplify/auth';
import { checkAuth, getAccessToken } from '../components/lib/CheckAuth';

export default function HomeFeedPage() {
  const [activities, setActivities] = React.useState([]);
  const [popped, setPopped] = React.useState(false);
  const [poppedReply, setPoppedReply] = React.useState(false);
  const [replyActivity, setReplyActivity] = React.useState({});
  const [user, setUser] = React.useState(null);
  const location = useLocation();
  const navigate = useNavigate();

const loadData = async () => {
    console.log('loadData called');
    const headers = {};

    // Get a fresh access token (auto-refreshes if expired)
    const accessToken = await getAccessToken();
    if (accessToken) {
      headers['Authorization'] = `Bearer ${accessToken}`;
    }

    const backend_url = `${process.env.REACT_APP_BACKEND_URL}/api/activities/home`;

    try {
      const res = await fetch(backend_url, {
        method: "GET",
        headers: headers,
      });

      const resJson = await res.json();
      if (res.status === 200) {
        setActivities(resJson)
      } else {
        console.log(res);
      }
    } catch (err) {
      console.log(err);
    }
  };

  const handleSignOut = async () => {
    try {
      await signOut();
      window.location.href = "/";
    } catch (error) {
      console.log('Error signing out: ', error);
    }
  };

  React.useEffect(() => {
    // This useEffect will run once when the component is mounted
    // to check the user's authentication status and then load data
    checkAuth(setUser);
    loadData();
  }, []);

  // The Crud button on any other page navigates here with { compose: true }
  // (backlog #40). Open the form, then clear the flag with a replace so a
  // refresh or Back does not reopen it.
  React.useEffect(() => {
    if (location.state && location.state.compose) {
      setPopped(true);
      navigate(location.pathname, { replace: true, state: {} });
    }
  }, [location.state, location.pathname, navigate]);

  React.useEffect(() => {
    // This effect runs whenever the `user` state changes
    // It will trigger loadData only after a user is authenticated
    if (user) {
      loadData(user);
    }
  }, [user]);

  return (
    <article>
      <DesktopNavigation user={user} active={'home'} setPopped={setPopped} handleSignOut={handleSignOut} />
      <div className='content'>
        <ActivityForm  
          popped={popped}
          setPopped={setPopped} 
          setActivities={setActivities} 
        />
        <ReplyForm 
          activity={replyActivity} 
          popped={poppedReply} 
          setPopped={setPoppedReply} 
          setActivities={setActivities} 
          activities={activities} 
        />
        <ActivityFeed 
          title="Home" 
          banner="home" 
          setReplyActivity={setReplyActivity} 
          setPopped={setPoppedReply} 
          activities={activities} 
        />
      </div>
      <DesktopSidebar user={user} />
    </article>
  );
}

import './NotificationsFeedPage.css';
import React from "react";

import DesktopNavigation  from '../components/DesktopNavigation';
import DesktopSidebar     from '../components/DesktopSidebar';
import ActivityFeed from '../components/ActivityFeed';

import { signOut } from 'aws-amplify/auth';
import { checkAuth } from '../components/lib/CheckAuth';

// Notifications are not built yet (backlog #31). The backend endpoint still
// returns bootcamp demo data, so this page no longer fetches it and shows an
// empty state instead (backlog #24).
export default function NotificationsFeedPage() {
  const [user, setUser] = React.useState(null);
  const dataFetchedRef = React.useRef(false);

  const handleSignOut = async () => {
    try {
      await signOut();
      window.location.href = "/";
    } catch (error) {
      console.log('Error signing out: ', error);
    }
  };

  React.useEffect(()=>{
    //prevents double call
    if (dataFetchedRef.current) return;
    dataFetchedRef.current = true;

    checkAuth(setUser);
  }, [])

  return (
    <article>
      <DesktopNavigation user={user} active={'notifications'} handleSignOut={handleSignOut} />
      <div className='content'>
        <ActivityFeed title="Notifications" banner="notifications" activities={[]} />
        <div
          className='notifications_empty'
          style={{ padding: '16px', color: 'rgba(255,255,255,0.5)' }}
        >
          No notifications yet.
        </div>
      </div>
      <DesktopSidebar user={user} />
    </article>
  );
}

import './PeoplePage.css';
import React from "react";
import { Link } from 'react-router-dom';

import DesktopNavigation  from '../components/DesktopNavigation';
import DesktopSidebar     from '../components/DesktopSidebar';
import ProfileAvatar from '../components/ProfileAvatar';

import { signOut } from 'aws-amplify/auth';
import { checkAuth, getAccessToken } from '../components/lib/CheckAuth';

export default function PeoplePage() {
  const [people, setPeople] = React.useState([]);
  const [popped, setPopped] = React.useState(false);
  const [user, setUser] = React.useState(null);
  const dataFetchedRef = React.useRef(false);

  const loadData = async () => {
    const headers = {};

    const accessToken = await getAccessToken();
    if (accessToken) {
      headers['Authorization'] = `Bearer ${accessToken}`;
    }

    try {
      const backend_url = `${process.env.REACT_APP_BACKEND_URL}/api/users`
      const res = await fetch(backend_url, {
        method: "GET",
        headers: headers,
      });
      let resJson = await res.json();
      if (res.status === 200) {
        setPeople(resJson)
      } else {
        console.log(res)
      }
    } catch (err) {
      console.log(err);
    }
  };

  const handleSignOut = async () => {
    try {
      await signOut();
      window.location.href = "/";
    } catch (error) {
      console.log('Error signing out: ', error);
    }
  };

  React.useEffect(()=>{
    //prevents double call
    if (dataFetchedRef.current) return;
    dataFetchedRef.current = true;

    checkAuth(setUser);
    loadData();
  }, [])

  return (
    <article>
      <DesktopNavigation user={user} active={'people'} setPopped={setPopped} handleSignOut={handleSignOut} />
      <div className='content'>
        <div className='activity_feed'>
          <div className='activity_feed_heading banner banner_people'>
            <div className='title'>People</div>
          </div>
          <div className='people_list'>
            {people.map(person => {
              return (
                <Link className="user" to={'/@' + person.handle} key={person.uuid}>
                  <ProfileAvatar id={person.cognito_user_id} name={person.display_name} />
                  <div className='identity'>
                    <span className="display_name">{person.display_name}</span>
                    <span className="handle">@{person.handle}</span>
                  </div>
                </Link>
              );
            })}
          </div>
        </div>
      </div>
      <DesktopSidebar user={user} />
    </article>
  );
}
